        return self._ws.remove(path)

    def clean(self):
        self._check_ws()
        return self._ws.clean()

    def info(self):
        self._check_ws()
        return {"name": self.name,
                "folder": self._folder,
                "packages": self._ws.packages()}

    def super_build_graph(self, deps_graph, profile_host, profile_build):
