                                                         ref.user, ref.channel,
                                                         lockfile=lockfile, remotes=remotes)
            ref, _ = exported_ref
            exported.append(ref)
        return exported


    def select_packages(self, packages):
        self._check_ws()
        editable = self.packages()
        packages = packages or []
        selected_editables = {}
        for ref, info in editable.items():
